"""Build the static review from the rendered proposal manifest."""
from html import escape
import json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
manifest = json.loads((root / 'manifest.json').read_text())
screens = manifest['screens']
groups = list(dict.fromkeys(screen['group'] for screen in screens))
style = '''
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f7f1e7;color:#343c31;font:16px/1.55 -apple-system,BlinkMacSystemFont,sans-serif}main{max-width:1280px;padding:48px 28px 80px;margin:auto}a{color:#3c654c;text-underline-offset:3px}h1,h2,h3{font-family:ui-rounded,-apple-system,sans-serif;line-height:1.15}h1{font-size:clamp(38px,6vw,64px);letter-spacing:-1.8px;margin:14px 0 20px}h2{font-size:30px;letter-spacing:-.6px;margin:42px 0 22px}h3{font-size:20px;letter-spacing:-.3px;margin:0 0 8px}p{margin:8px 0 16px}.eyebrow{font-size:12px;letter-spacing:.12em;text-transform:uppercase;font-weight:650;color:#646357}.lead{font-size:21px;line-height:1.5;max-width:840px}.intro{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:30px 0}.intro>div{padding:24px;border:1px solid #e6dfd2;background:#fffcf6;border-radius:24px}.intro p{margin:0;color:#646357}.links{display:flex;gap:18px;flex-wrap:wrap;font-size:14px}.toolbar{position:sticky;top:0;z-index:10;background:#f7f1e7f5;backdrop-filter:blur(20px);padding:16px 0;display:flex;gap:16px;align-items:end;flex-wrap:wrap;border-bottom:1px solid #e6dfd2}.toolbar label{font-size:13px;font-weight:600;display:block;margin-bottom:5px}select,input{font:inherit;border:1px solid #a19e8d;border-radius:12px;background:#fffcf6;color:#343c31;padding:11px 14px;min-height:46px}input{width:min(340px,100%)}.field{max-width:100%}.toolbar .count{font-size:13px;color:#646357;align-self:center;margin-left:auto}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px;align-items:start}.card{background:#fffcf6;border:1px solid #e6dfd2;border-radius:24px;padding:18px;min-width:0}.card p{font-size:14px;color:#646357;line-height:1.5}.card .frame{background:#eae6dc;border-radius:18px;padding:16px;margin:14px 0 18px;display:flex;align-items:center;justify-content:center;min-height:200px;overflow:hidden}.card.calendar .frame,.card.context .frame{padding:0;background:#f7f1e7}.card img{display:block;width:100%;height:auto;max-width:364px}.card.calendar img{max-width:294px}.card.context img{max-width:294px}.card .frame.small img{max-width:170px}.card .dimensions{font-size:12px;color:#646357;margin:0 0 6px}.card details{font-size:13px;margin:12px 0 0;border-top:1px solid #e6dfd2;padding-top:12px;color:#646357}.card details summary{color:#3c654c;cursor:pointer;min-height:28px}.source-link{font-size:13px}.references{background:#fffcf6;border:1px solid #e6dfd2;border-radius:20px;padding:20px;margin-top:30px}.references summary{font-weight:600;cursor:pointer}.reference-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin-top:18px}.reference-grid img{width:100%;border-radius:14px}.reference-grid figcaption{font-size:13px;color:#646357}figure{margin:0}.note{font-size:14px;color:#646357;max-width:950px}footer{border-top:1px solid #e6dfd2;padding-top:24px;margin-top:48px;font-size:14px}a:focus-visible,summary:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #3c654c;outline-offset:4px}section[hidden],article[hidden]{display:none!important}@media(max-width:1000px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.reference-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:620px){main{padding:28px 18px 60px}.intro,.grid{grid-template-columns:1fr}.toolbar{gap:12px}.toolbar .count{width:100%;margin:0}select,input{width:100%}.field{width:100%}.lead{font-size:18px}.card.calendar img,.card.context img{max-width:330px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
'''
parts = [f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Family Hub · Calendar & widgets</title><style>{style}</style><main><header><div class="eyebrow">Family Hub · iPhone design review · 21 October 2026</div><h1>Calendar &amp; widgets</h1><p class="lead">The Calendar you use today, in Warm Sage Cosier. A new widget set built around meals and the next event.</p><div class="links"><a href="../index.html">Original audit</a><a href="README.md">Design notes and interactions</a><a href="../week-options/index.html#week-compact">Selected Week view · compact all-day</a><a href="calendar-overview.png">Calendar board</a><a href="widget-overview.png">Widget board</a><a href="manifest.json">Image manifest</a><a href="validation.json">Validation</a></div><div class="intro"><div><h3>Calendar: keep the familiar views</h3><p>Year, Month, Day, and Week stay in place. Keep the zoom, swipe, Today, Back, and view-menu behaviour. Apply the warm canvas, sage selection, and soft surfaces.</p></div><div><h3>Widgets: make the useful things clear</h3><p>Use Today medium as the default. Put the next event beside dinner. Offer Tonight, Meal plan, Up next, and Chores as focused choices.</p></div></div><p class="note">These are static proposals, not simulator captures or app changes. Calendar data, icon strokes, native controls, and system materials are illustrative. The clear and tinted widgets show design intent; WidgetKit controls their final appearance.</p></header><div class="toolbar"><div class="field"><label for="group">Show</label><select id="group"><option value="all">All {len(screens)} proposals</option>''']
for group in groups:
    parts.append(f'<option value="{escape(group)}">{escape(group)}</option>')
parts.append('''</select></div><div class="field"><label for="search">Find a screen or state</label><input id="search" type="search" placeholder="For example: week, dinner, dark"></div><span class="count" id="count" role="status" aria-live="polite"></span></div>''')
for group in groups:
    parts.append(f'<section data-group="{escape(group)}"><h2>{escape(group)}</h2><div class="grid">')
    for screen in (screen for screen in screens if screen['group'] == group):
        kind = 'calendar' if group == 'Calendar' else 'context' if group == 'Context' else 'widget'
        small = screen['width'] <= 210
        text = ' '.join(str(screen[key]) for key in ['title', 'description', 'notes']).lower()
        parts.append(f'''<article class="card {kind}" id="{screen['id']}" data-search="{escape(text)}"><h3>{escape(screen['title'])}</h3><p>{escape(screen['description'])}</p><p class="dimensions">{screen['width']} × {screen['height']} points · PNG at 3×</p><div class="frame {'small' if small else ''}"><a href="{screen['file']}"><img loading="lazy" width="{screen['width']}" height="{screen['height']}" src="{screen['file']}" alt="{escape(screen['title'])} proposal"></a></div><a class="source-link" href="source/mockups.html?screen={screen['id']}">Open editable layout</a>''')
        if screen['notes']:
            parts.append(f'<details><summary>Interaction notes</summary><p>{escape(screen["notes"])}</p></details>')
        parts.append('</article>')
    parts.append('</div></section>')
parts.append('''<details class="references"><summary>Existing Calendar layout references</summary><p class="note">These earlier simulator captures document the existing layouts. The proposals use different sample dates. They are layout references, not pixel comparisons.</p><div class="reference-grid">''')
for mode in ['year', 'month', 'day', 'week']:
    parts.append(f'<figure><a href="../implementation/calendar/calendar-{mode}.png"><img loading="lazy" src="../implementation/calendar/calendar-{mode}.png" alt="Existing {mode} layout"></a><figcaption>{mode.capitalize()} · earlier simulator capture</figcaption></figure>')
parts.append('''</div></details><footer><p>Read the <a href="README.md">design notes</a> for widget tap targets, data needs, and deliberate adaptations.</p><p>Reference: <a href="https://developer.apple.com/design/human-interface-guidelines/widgets">Apple’s widget guidance</a> and <a href="https://developer.apple.com/documentation/widgetkit/optimizing-your-widget-for-accented-rendering-mode-and-liquid-glass">widget rendering modes</a>.</p></footer></main><script>const group=document.getElementById('group'),search=document.getElementById('search');function filter(){let count=0;for(const section of document.querySelectorAll('section[data-group]')){let shown=0;for(const card of section.querySelectorAll('article')){card.hidden=(group.value!=='all'&&section.dataset.group!==group.value)||!card.dataset.search.includes(search.value.toLowerCase());if(!card.hidden)shown++;}section.hidden=shown===0;count+=shown;}document.getElementById('count').textContent=count+' proposals';}group.addEventListener('change',filter);search.addEventListener('input',filter);filter();</script></html>''')
(root / 'index.html').write_text(''.join(parts))
print(f'Built the gallery for {len(screens)} proposals.')
